import openpyxl
from openpyxl.utils import coordinate_to_tuple

orig_path='/mnt/hhq/data/MiMotable/进销存日报表.xlsx'
tmp_path='进销存日报表_template_2502_input.xlsx'
out_path='进销存日报表_template_2502_filled.xlsx'

orig=openpyxl.load_workbook(orig_path, data_only=False)['Sheet1']
wb=openpyxl.load_workbook(tmp_path, data_only=False)
ws=wb['Sheet1']

# Record formulas in template before changes
formulas_before={}
for row in ws.iter_rows():
    for cell in row:
        if isinstance(cell.value, str) and cell.value.startswith('='):
            formulas_before[cell.coordinate]=cell.value

count=0
for r in range(2,11):
    for c in range(2,19):
        coord=f'{openpyxl.utils.get_column_letter(c)}{r}'
        val=orig.cell(row=r,column=c).value
        if val is not None and not (isinstance(val,str) and val.startswith('=')):
            ws.cell(row=r,column=c).value = val
            count+=1
            print('set', coord, repr(val))

print('filled', count)
wb.save(out_path)

# Verify formulas unchanged after save
wb2=openpyxl.load_workbook(out_path, data_only=False)
ws2=wb2['Sheet1']
formulas_after={}
for row in ws2.iter_rows():
    for cell in row:
        if isinstance(cell.value, str) and cell.value.startswith('='):
            formulas_after[cell.coordinate]=cell.value
print('formulas before', len(formulas_before), 'after', len(formulas_after))
for k in sorted(set(formulas_before)|set(formulas_after)):
    if formulas_before.get(k)!=formulas_after.get(k):
        print('FORMULA CHANGED', k, formulas_before.get(k), formulas_after.get(k))
print('formula change check done')
